
"use client";

import ReferralManagement from './routes/home';
import { createTicTacToe } from './routes/tictactoe';
import { useEffect } from 'react';

export default function Home() {
  useEffect(() => {
    // Initialize Tic Tac Toe when component mounts
    createTicTacToe('tictactoe-container');
  }, []);

  return (
    <div>
      <ReferralManagement />
      <div id="tictactoe-container" style={{ marginTop: '20px' }}></div>
    </div>
  );
}
